function SPHERICAL-PERSISTENCE-VIA-STEREO(P, k, eps_max):
  # P = {p_1,...,p_N} unit vectors in R^{n+1}, each p = (u, h)
  for each p = (u, h) in P:
      x <- u / (1 - h)                 # forward stereographic projection to R^n
  X <- {x_1, ..., x_N}
  for each x_i in X:
      w_i <- sqrt(1 + ||x_i||^2)       # conformal weight
  T <- build_kd_tree(X)
  for each pair (i, j) with ||x_i - x_j|| <= query_radius(eps_max):
      d_w[i][j] <- 2 * ||x_i - x_j|| / (w_i * w_j)
  Dgm_0..k <- VIETORIS_RIPS_PERSISTENCE(X, d_w, k, eps_max)
  return Dgm_0..k

